const test = require("node:test");
const assert = require("node:assert");
const { roundCents } = require("../src/money");
test("rounds half-even", () => { assert.strictEqual(roundCents(0.125), 0.12); });
test("rounds normally", () => { assert.strictEqual(roundCents(1.237), 1.24); });
